import React from "react";
import { TESTIMONIALS } from "./Content";
import { Quote, Star } from "lucide-react";

export default function Testimonials() {
  const items = [...TESTIMONIALS, ...TESTIMONIALS];

  return (
    <section
      id="testimonials"
      className="relative py-24 md:py-32 overflow-hidden"
      data-testid="testimonials-section"
      style={{ background: "linear-gradient(180deg, #0d0405 0%, #14060a 50%, #0d0405 100%)" }}
    >
      <div className="px-6 md:px-12 lg:px-24 mb-12">
        <div className="overline mb-4">Voices</div>
        <h2 className="serif" style={{ fontSize: "clamp(36px, 5vw, 72px)", lineHeight: 1.02, fontWeight: 300, color: "#fffff0", maxWidth: 820 }}>
          What decorators across India <span style={{ color: "#d4af37", fontStyle: "italic" }}>keep saying.</span>
        </h2>
      </div>

      <div className="relative">
        <div className="absolute left-0 top-0 bottom-0 w-32 z-10 pointer-events-none" style={{ background: "linear-gradient(to right, #0d0405, transparent)" }} />
        <div className="absolute right-0 top-0 bottom-0 w-32 z-10 pointer-events-none" style={{ background: "linear-gradient(to left, #0d0405, transparent)" }} />

        <div className="marquee py-2">
          {items.map((t, i) => (
            <article
              key={i}
              className="glass gold-border rounded-sm p-7 md:p-9 flex-shrink-0"
              style={{ width: 460 }}
              data-testid={`testimonial-${i}`}
            >
              <Quote size={26} strokeWidth={1.4} style={{ color: "#d4af37", marginBottom: 14 }} />
              <p className="serif" style={{ color: "#fffff0", fontSize: 20, lineHeight: 1.45, fontWeight: 400, minHeight: 130 }}>
                "{t.quote}"
              </p>
              <div className="mt-5 flex items-center justify-between">
                <div>
                  <div style={{ color: "#f7e7ce", fontWeight: 500, letterSpacing: "0.04em" }}>
                    {t.name}
                  </div>
                  <div className="overline mt-1" style={{ color: "rgba(247,231,206,0.6)" }}>
                    {t.role} · {t.city}
                  </div>
                </div>
                <div className="flex items-center gap-1">
                  {Array.from({ length: 5 }).map((_, idx) => (
                    <Star key={idx} size={14} fill="#d4af37" strokeWidth={0} />
                  ))}
                </div>
              </div>
              <div className="mt-4 text-[10px] tracking-[0.22em] uppercase" style={{ color: "#d4af37" }}>
                Verified Customer
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}
